code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # Find the full separator line.
    sep_r = next((r for r in range(h) if all(g[r][c] == 2 for c in range(w))), None)
    sep_c = next((c for c in range(w) if all(g[r][c] == 2 for r in range(h))), None)
    if sep_r is None and sep_c is None:
        return g
    counts = {}
    for row in g:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    pts = [(r, c, g[r][c]) for r in range(h) for c in range(w) if g[r][c] not in (2, bg)]
    if not pts:
        return g
    if sep_r is not None:
        rows = [r for r, c, v in pts]
        if min(rows) > sep_r:  # object below line; pack it upward
            dr = sep_r + 1 - min(rows)
        else:                  # object above line; pack it downward
            dr = sep_r - 1 - max(rows)
        moved = [(r + dr, c, v) for r, c, v in pts]
        for r, c, v in pts:
            g[r][c] = bg
        for r, c, v in moved:
            g[r][c] = v
        nearfar = max(r for r, c, v in moved) + 1 if max(r for r, c, v in moved) < sep_r else min(r for r, c, v in moved) - 1
        if 0 <= nearfar < h:
            g[nearfar] = [8] * w
    else:
        cols = [c for r, c, v in pts]
        if max(cols) < sep_c:  # object left of line; pack it rightward
            dc = sep_c - 1 - max(cols)
        else:                  # object right of line; pack it leftward
            dc = sep_c + 1 - min(cols)
        moved = [(r, c + dc, v) for r, c, v in pts]
        for r, c, v in pts:
            g[r][c] = bg
        for r, c, v in moved:
            g[r][c] = v
        far = min(c for r, c, v in moved) - 1 if max(c for r, c, v in moved) < sep_c else max(c for r, c, v in moved) + 1
        if 0 <= far < w:
            for r in range(h):
                g[r][far] = 8
    return g
'''
